import{_ as t,c as i,o as a,a9 as r}from"./chunks/framework.Bqk8xQPS.js";const h=JSON.parse('{"title":"Event Bridges","description":"Choose the right PURISTA event bridge and understand delivery semantics","frontmatter":{"title":"Event Bridges","description":"Choose the right PURISTA event bridge and understand delivery semantics","order":301000},"headers":[],"relativePath":"handbook/3_eco_system/eventbridges/index.md","filePath":"handbook/3_eco_system/eventbridges/index.md","lastUpdated":1775039954000}'),n={name:"handbook/3_eco_system/eventbridges/index.md"};function o(d,e,s,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="event-bridges" tabindex="-1">Event Bridges <a class="header-anchor" href="#event-bridges" aria-label="Permalink to “Event Bridges”">​</a></h1><p>Event bridges are the transport backbone of PURISTA. They determine routing, scaling behavior, durability options, and delivery guarantees.</p><h2 id="support-matrix" tabindex="-1">Support matrix <a class="header-anchor" href="#support-matrix" aria-label="Permalink to “Support matrix”">​</a></h2><p>| bridge | scale out | durable backlog | typical delivery mode | late response handling | stream support (<code>openStream</code>) | |---|---😐---😐---|---😐 | <a href="./default_event_bridge.html">Default</a> | no | no | at-most-once (in-memory) | ignored with warning after timeout | yes | | <a href="./amqp.html">AMQP</a> | yes | yes | at-least-once for durable queues with manual ack | ignored with warning after timeout | no (currently) | | <a href="./mqtt.html">MQTT</a> | yes | broker-dependent | QoS dependent (0/1/2) | ignored with warning after timeout | no (currently) | | <a href="./nats.html">NATS</a> | yes | yes with JetStream, no with core NATS | at-most-once on core NATS, at-least-once with JetStream durable consumers | not applicable | no (currently) | | <a href="./dapr.html">Dapr</a> | yes | component-dependent | component-dependent (often at-least-once) | not applicable | no (currently) |</p><h3 id="queue-bridge-support" tabindex="-1">Queue bridge support <a class="header-anchor" href="#queue-bridge-support" aria-label="Permalink to “Queue bridge support”">​</a></h3><table tabindex="0"><thead><tr><th>queue bridge package</th><th>preferred workloads</th><th>compatible event bridges</th></tr></thead><tbody><tr><td><code>@purista/core</code> default queue bridge</td><td>local dev, unit tests, single instance deployments</td><td>Any (in-memory inside the service)</td></tr><tr><td><code>@purista/redis-queue-bridge</code></td><td>production pull-based CQRS, delayed jobs, AI worker pools</td><td>Default, AMQP, MQTT, NATS, Dapr (redis acts as the queue backend while the event bridge handles command/subscription traffic)</td></tr></tbody></table><p>Future queue bridge packages will live next to the event bridge adapters (e.g. <code>@purista/nats-queue-bridge</code>) once those providers expose reliable pull + lease semantics. When evaluating infrastructure, pick an event bridge + queue bridge pair that matches your durability and scaling needs.</p><p>See the dedicated <a href="./../queue_bridges/">Queue Bridges</a> page for wiring guidance and capability details.</p><h2 id="delivery-semantics-in-practice" tabindex="-1">Delivery semantics in practice <a class="header-anchor" href="#delivery-semantics-in-practice" aria-label="Permalink to “Delivery semantics in practice”">​</a></h2><p>PURISTA itself provides typed message contracts and processing flow. Delivery guarantees come from the selected bridge + broker/component configuration.</p><ul><li><code>at-most-once</code>: low latency, but a message can be lost on failures.</li><li><code>at-least-once</code>: safer delivery, but duplicates are possible.</li><li><code>exactly-once</code>: generally not guaranteed end-to-end in distributed systems; design handlers to be idempotent.</li></ul><p>Late command responses are normalized across invoke-capable bridges in this slice. Once the caller-side timeout fires, PURISTA keeps a short-lived tombstone for the correlation id and ignores any later response with a warning instead of raising a bridge error.</p><p>Subscription retry and dead-letter handling are advisory bridge-level concerns. Service definitions can declare bounded consumer failure handling, but each adapter decides whether it can honor that through broker-native features, bridge-emulated dead-lettering, or documented best-effort fallback.</p><h2 id="reliability-checklist" tabindex="-1">Reliability checklist <a class="header-anchor" href="#reliability-checklist" aria-label="Permalink to “Reliability checklist”">​</a></h2><ul><li>configure broker durability/retry features explicitly</li><li>keep bridge settings identical across instances</li><li>implement idempotency in command/subscription side effects</li><li>define timeout/retry policies intentionally (do not rely on defaults only)</li><li>keep subscription retry budgets bounded and route poison messages to a dead-letter target</li><li>verify shutdown, readiness, and reconnect semantics in integration tests</li><li>test reconnect and broker outage scenarios in integration tests</li></ul><h2 id="when-to-use-which-bridge" tabindex="-1">When to use which bridge <a class="header-anchor" href="#when-to-use-which-bridge" aria-label="Permalink to “When to use which bridge”">​</a></h2><ul><li><code>DefaultEventBridge</code>: local development, single-instance deployments, stream development.</li><li><code>AMQP</code>: production systems with durable queues/retries and strong operational control.</li><li><code>MQTT</code>: IoT/edge and broker setups where topic/QoS tuning is central.</li><li><code>NATS</code>: low-latency eventing where simple operations are preferred.</li><li><code>NATS</code> with JetStream: good fit when you want bounded subscription retries and dead-letter subjects without introducing a separate queue backend.</li><li><code>Dapr</code>: polyglot/service-mesh environments leveraging Dapr components.</li></ul>',17)])])}const b=t(n,[["render",o]]);export{h as __pageData,b as default};
